   153    int   av_count;            /* The number of bucket_avail entries. */
   154    avail_elem bucket_avail[BUCKET_AVAIL];  /* Distributed avail. */
   155    int   bucket_bits;         /* The number of bits used to get here. */
   156    int   count;               /* The number of element buckets full. */
   157    bucket_element h_table[1]; /* The table.  Make it look like an array.*/
   158  } hash_bucket;
