    60  _gdbm_read_entry (GDBM_FILE dbf, int elem_loc)
    61  {
    62    int rc;
    63    off_t file_pos;
    64    int key_size;
    65    int data_size;
    66    size_t dsize;
    67    data_cache_elem *data_ca;
    68
    69    /* Is it already in the cache? */
    70    if (dbf->cache_entry->ca_data.elem_loc == elem_loc)
    71      return dbf->cache_entry->ca_data.dptr;
    72
    73    if (!gdbm_bucket_element_valid_p (dbf, elem_loc))
    74      {
    75        GDBM_SET_ERRNO (dbf, GDBM_BAD_HASH_TABLE, TRUE);
    76        return NULL;
    77      }
    78
    79    /* Set sizes and pointers. */
    80    key_size = dbf->bucket->h_table[elem_loc].key_size;
    81    data_size = dbf->bucket->h_table[elem_loc].data_size;
    82    dsize = key_size + data_size;
    83    data_ca = &dbf->cache_entry->ca_data;
    84
    85    /* Make sure data_ca has sufficient space to accomodate both
    86       key and content. */
    87    if (dsize <= data_ca->dsize)
    88      {
    89        if (data_ca->dsize == 0)
    90          {
    91            data_ca->dptr = malloc (1);
    92            if (data_ca->dptr)
    93              data_ca->dsize = 1;
    94            else
    95              {
    96                GDBM_SET_ERRNO2 (dbf, GDBM_MALLOC_ERROR, FALSE, GDBM_DEBUG_LOOKUP);
    97                _gdbm_fatal (dbf, _("malloc error"));
    98                return NULL;
    99              }
   100          }
   101      }
   102    else
   103      {
   104        char *p = realloc (data_ca->dptr, dsize);
   105        if (p)
   106          {
   107            data_ca->dptr = p;
   108            data_ca->dsize = dsize;
   109          }
   110        else
   111          {
   112            GDBM_SET_ERRNO2 (dbf, GDBM_MALLOC_ERROR, FALSE, GDBM_DEBUG_LOOKUP);
   113            _gdbm_fatal (dbf, _("malloc error"));
   114            return NULL;
   115          }
   116      }
   117
   118    /* Read into the cache. */
   119    file_pos = gdbm_file_seek (dbf, dbf->bucket->h_table[elem_loc].data_pointer,
   120                               SEEK_SET);
   121    if (file_pos != dbf->bucket->h_table[elem_loc].data_pointer)
   122      {
   123        GDBM_SET_ERRNO2 (dbf, GDBM_FILE_SEEK_ERROR, TRUE, GDBM_DEBUG_LOOKUP);
   124        _gdbm_fatal (dbf, _("lseek error"));
   125        return NULL;
   126      }
   127
   128    rc = _gdbm_full_read (dbf, data_ca->dptr, key_size+data_size);
   129    if (rc)
   130      {
   131        GDBM_DEBUG (GDBM_DEBUG_ERR|GDBM_DEBUG_LOOKUP|GDBM_DEBUG_READ,
   132                   "%s: error reading entry: %s",
   133                   dbf->name, gdbm_db_strerror (dbf));
   134        dbf->need_recovery = TRUE;
   135        _gdbm_fatal (dbf, gdbm_db_strerror (dbf));
   136        return NULL;
   137      }
   138
   139    /* Set up the cache. */
   140    data_ca->key_size = key_size;
   141    data_ca->data_size = data_size;
   142    data_ca->elem_loc = elem_loc;
   143    data_ca->hash_val = dbf->bucket->h_table[elem_loc].hash_value;
   144
   145    return data_ca->dptr;
   146  }
