    24  /* This hash function computes a GDBM_HASH_BITS-bit value.  The value is used
    25     to index the hash directory using the top n bits.  It is also used in a
    26     hash bucket to find the home position of the element by taking the value
    27     modulo the bucket hash table size. */
    28
    29  int
    30  _gdbm_hash (datum key)
    31  {
    32    unsigned int value;   /* Used to compute the hash value.  */
    33    int   index;          /* Used to cycle through random values. */
    34
    35    /* Set the initial value from key. */
    36    value = 0x238F13AFu * key.dsize;
    37    for (index = 0; index < key.dsize; index++)
    38      value = (value + (((unsigned)key.dptr[index]) << ((unsigned) index * 5 % 24))) & 0x7FFFFFFF;
    39
    40    value = (1103515243u * value + 12345) & 0x7FFFFFFF;
    41
    42    /* Return the value. */
    43    return((int) value);
    44  }
