    52  void
    53  _gdbm_hash_key (GDBM_FILE dbf, datum key, int *hash, int *bucket, int *offset)
    54  {
    55    int hashval = _gdbm_hash (key);
    56    *hash = hashval;
    57    *bucket = _gdbm_bucket_dir (dbf, hashval);
    58    *offset = hashval % dbf->header->bucket_elems;
    59  }
